const q = $input.first().json.query || {};
const expected = "F1h0b14n4";
const ok = q["hub.mode"] === "subscribe" && q["hub.verify_token"] === expected;
return [{
  json: {
    ok,
    responseBody: ok ? String(q["hub.challenge"] || "") : "Forbidden",
  }
}];

// ============================================================================
// 1. Extraire sender + texte du payload webhook Meta. Ignore silencieusement
//    tout ce qui n'est pas un message texte (statuts de livraison, etc.).
// ============================================================================
const body = $input.first().json.body || {};
let sender = null, text = null;
for (const entry of (body.entry || [])) {
  for (const change of (entry.changes || [])) {
    for (const msg of ((change.value || {}).messages || [])) {
      if (msg.type === "text") { sender = msg.from; text = msg.text.body; }
    }
  }
}
if (!sender) return [];

// ============================================================================
// 2. Whitelist équipe Nuklear. Laisser vide = tout le monde autorisé.
// ============================================================================
// Vide par défaut = tout le monde autorisé (comme whatsapp.py::allowed_senders() côté Python).
// Remplir avec des numéros séparés par des virgules pour activer la whitelist équipe Nuklear.
const ALLOWED_SENDERS = ""; // ex: "+261340000000,+261320000000"
const allowedList = ALLOWED_SENDERS.split(",").map(s => s.trim()).filter(Boolean);
if (allowedList.length && !allowedList.includes(sender)) {
  return [{ json: { sender, needsBrain: false, text: "⛔ Accès réservé à l'équipe Nuklear.", image_url: null } }];
}

// ============================================================================
// 3. État de conversation persistant (mémoire n8n native -- survit entre
//    exécutions, pas de base de données requise).
// ============================================================================
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
const state = staticData.sessions[sender] || { stage: "idle", platform: null, current_idea: null, refine_notes: [] };

// ============================================================================
// 4. Parsing de commande.
// ============================================================================
const HELP_TEXT = [
  "🤖 *Nuklear Content Agent* — commandes disponibles:",
  "",
  "1️⃣ *gen image insta* / *gen image facebook*",
  "   → Idée de visuel basée sur les tendances + concurrents en temps réel. Idée libre : `gen image insta: astuce SEO local`",
  "",
  "2️⃣ *gen video*",
  "   → Prompt vidéo précis (avant/après, astuce, mythe vs réalité...).",
  "",
  "🎯 *gen collection: <idée>* / *gen avant apres: <idée>* / *gen annonce: <idée>*",
  "   → Force directement ce format (grille de photos / split-screen / paysage texte), sans dépendre de la détection automatique.",
  "",
  "3️⃣ *gen recrutement: <poste> | <contrat> | <lieu> | <email>*",
  "   → Visuel d'offre d'emploi prêt à publier. Ex: `gen recrutement: Développeur Full Stack Senior | CDI | Antananarivo | recrutement@nuklear.io`",
  "   → Contrat/lieu/email optionnels (valeurs par défaut Nuklear si omis).",
  "",
  "4️⃣ *actus* / *news*",
  "   → Actualités secteur + mouvements concurrents.",
  "",
  "Après une proposition :",
  "   ✅ *ok* / *valide* → génère le visuel final",
  "   🔄 *encore* / *autre* → relance une recherche d'idées",
  "   ✏️ *affine: <remarque>* → ajuste l'idée",
].join("\n");

function stripPunct(s) {
  const t = s.replace(/[\s!.?,;]+$/, "");
  return t || s;
}

function detectPlatform(low) {
  const aliases = [["insta", "instagram"], ["instagram", "instagram"], ["ig", "instagram"], ["fb", "facebook"], ["facebook", "facebook"]];
  for (const [alias, canon] of aliases) {
    if (new RegExp("\\b" + alias + "\\b").test(low)) return canon;
  }
  return null;
}

function splitFreeText(t) {
  const i = t.indexOf(":");
  if (i === -1) return [t.trim(), ""];
  return [t.slice(0, i).trim(), t.slice(i + 1).trim()];
}

const raw = text.trim();
const norm = stripPunct(raw.toLowerCase()) || raw.toLowerCase();

let cmd = "unknown", platform = null, freeText = "";

if (["help", "aide", "?", "menu"].includes(norm)) cmd = "help";
else if (["ok", "valide", "validé", "go", "oui", "✅"].includes(norm)) cmd = "validate";
else if (["encore", "autre", "autres", "relance", "🔄", "non"].includes(norm)) cmd = "refresh";
else {
  const refineMatch = raw.match(/^(affine|adapte|change)\s*[:\-]\s*([\s\S]+)$/i);
  if (refineMatch) {
    cmd = "refine"; freeText = refineMatch[2].trim();
  } else {
    const [head, free] = splitFreeText(raw);
    const lowHead = head.toLowerCase();
    if (/\b(actus?|news|actualit)/.test(lowHead)) cmd = "news";
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(recrutement|recrute|embauche)\b/.test(lowHead)) { cmd = "gen_recrutement"; freeText = free; }
    // Commandes FORCÉES : outrepassent la classification automatique du LLM pour donner un accès
    // direct et fiable à une catégorie précise (utile pour tester/forcer un format sans dépendre de
    // la détection automatique, qui peut varier selon l'idée synthétisée).
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(collection)\b/.test(lowHead)) { cmd = "gen_collection"; platform = detectPlatform(lowHead); freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(avant.?apr[eè]s)\b/.test(lowHead)) { cmd = "gen_avant_apres"; platform = detectPlatform(lowHead); freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(annonce)\b/.test(lowHead)) { cmd = "gen_annonce"; platform = detectPlatform(lowHead); freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\bvid/.test(lowHead)) { cmd = "gen_video"; freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(image|visuel|post)/.test(lowHead)) {
      cmd = "gen_image"; platform = detectPlatform(lowHead); freeText = free;
    }
  }
}

// ============================================================================
// 5. Commandes "rapides" (aucun appel externe nécessaire) traitées directement ici.
// ============================================================================
if (cmd === "help") return [{ json: { sender, needsBrain: false, text: HELP_TEXT, image_url: null } }];
if (cmd === "unknown") return [{ json: { sender, needsBrain: false, text: "Je ne comprends que des commandes précises. Tape *aide* pour voir la liste.", image_url: null } }];
if (cmd === "validate" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Rien à valider. Lance d'abord *gen image insta*.", image_url: null } }];
if (cmd === "refresh" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Aucune idée en cours. Lance d'abord *gen image insta* ou *gen image facebook*.", image_url: null } }];
if (cmd === "refine" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Aucune idée à affiner. Lance d'abord une génération d'image.", image_url: null } }];

// ============================================================================
// 6. Limite quotidienne par expéditeur -- protège les forfaits gratuits partagés
//    par toute l'équipe (Tavily 1000 req/mois, Ollama Cloud, Cloudinary 25
//    crédits/mois). Sans ça, un usage un peu intensif épuise le quota du mois
//    en quelques jours sans que personne ne s'en rende compte à l'avance.
// ============================================================================
const DAILY_LIMIT_PER_SENDER = 15; // ~450/mois si utilisé tous les jours -- ajuster si besoin
const today = new Date().toISOString().slice(0, 10);
staticData.usage = staticData.usage || {};
const usageKey = `${sender}:${today}`;
staticData.usage[usageKey] = staticData.usage[usageKey] || 0;
if (staticData.usage[usageKey] >= DAILY_LIMIT_PER_SENDER) {
  return [{ json: {
    sender, needsBrain: false,
    text: `⏳ Limite quotidienne atteinte (${DAILY_LIMIT_PER_SENDER} générations/jour) pour préserver les forfaits gratuits partagés par l'équipe. Réessaie demain.`,
    image_url: null,
  } }];
}
staticData.usage[usageKey] += 1;

// ============================================================================
// 7. Tout le reste a besoin du cerveau (recherche + LLM + éventuellement image).
// ============================================================================
return [{ json: {
  sender, needsBrain: true, command: cmd,
  platform: platform || state.platform || "instagram",
  freeText, state,
} }];

// ============================================================================
// Config -- à remplacer avant activation.
// ============================================================================
const TAVILY_KEY = "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";
const OLLAMA_KEY = "fd57fa4c47304feb8b9fc67d0b08ed18.s-ok3iU3Ka3UTgle0Mx2Bqyg";
const OLLAMA_MODEL = "gpt-oss:20b-cloud";
const OLLAMA_FALLBACK_MODEL = "gemma3:4b-cloud";
const NUKLEAR_POSITIONING = "agence marketing / growth / SEO";
const BRAND_VOICE = "humoristique, sarcastique, décontracté mais expert — jamais corporate-plat";
const CLOUDINARY_CLOUD = "pme0bbhb";
const LOGO_PUBLIC_ID = "Logo_gtorte";
// Icône [N] à poser À GAUCHE du wordmark ci-dessus (asset stocké, même cloud Cloudinary --
// aucune dépendance "Fetched URL"). Public_id extrait de l'URL fournie par l'utilisateur.
const MINILOGO_PUBLIC_ID = "MiniLogo_v6kxzf";
// ⚙️ Lueur de fond dégradée. DÉSACTIVÉE par défaut : le rendu par défaut redevient le poster épuré
// déjà validé. La v1 échouait car elle cumulait DEUX effets e_ dans un même composant Cloudinary
// (e_colorize + e_blur) -- interdit : un seul e_ par composant, sinon le flou est ignoré et le halo
// devient un RECTANGLE PLEIN. Syntaxe corrigée ci-dessous (un e_ par composant). À ne repasser à true
