// Si renseigné, ce public_id UNIQUE est TOUJOURS utilisé (utile pour figer/tester un fond précis) --
// prioritaire sur la bibliothèque ci-dessous. Placeholder = bibliothèque active.
const BRAND_BG_PUBLIC_ID = "REPLACE_WITH_BRAND_BG_PUBLIC_ID";
// 🎨 BIBLIOTHÈQUE de fonds dégradés "du même genre" : un fond DIFFÉRENT est tiré au hasard à CHAQUE
// génération pour varier le visuel tout en gardant la charte (dégradé sombre + anneau/forme). Pour
// ajouter un fond : exportez-le en PNG depuis Canva, ajoutez-le au dépôt GitHub (ex: fond2.png,
// fond3.png...), puis collez son URL brute ("raw.githubusercontent.com") ci-dessous -- une ligne par
// fond. Chaque source est uploadée vers Cloudinary et mise en cache INDÉPENDAMMENT (une seule fois
// par source, $getWorkflowStaticData) : les exécutions suivantes ne re-téléchargent jamais un fond
// déjà connu, même si un AUTRE membre du tableau est tiré au sort entre-temps.
const BRAND_BG_SOURCES = [
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond2.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond4.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond5.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond6.png",
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond7.png",
  // fond3.png EXCLU ICI : format PAYSAGE (720x392), utilisé par le pool dédié ci-dessous.
];
// Fond(s) dédiés au format PAYSAGE (catégorie "annonce", canevas 1080x588 -- même ratio que fond3.png,
// aucun recadrage nécessaire). Même mécanique de rotation + cache que le pool portrait, dans un
// tableau séparé car les deux formats ne sont PAS interchangeables.
const BRAND_BG_SOURCES_LANDSCAPE = [
  "https://raw.githubusercontent.com/Fihobiana87/Nuklear/main/fond3.png",
];
// Nom d'un "upload preset" Cloudinary en mode UNSIGNED (Settings > Upload > Upload presets).
// Sert au montage par UPLOAD (Cloudinary va chercher l'image lui-même, côté serveur), qui NE
// dépend PAS du réglage "Fetched URL" -- lequel est désactivé par défaut sur les comptes récents
// et bloque toute URL /image/fetch/ avec une 400 (cause racine du "montage indisponible").
// Laisser le placeholder si non configuré : le workflow bascule alors sur /image/fetch/ (si activé)
// puis, en dernier recours, sur l'image brute -- il fonctionne dans tous les cas.
const CLOUDINARY_UPLOAD_PRESET = "nuklear_unsigned";
// ⭐ CHEMIN LE PLUS FIABLE ET LE PLUS FIDÈLE À LA CHARTE. public_id d'un FOND DE MARQUE vierge
// (le gabarit sombre Nuklear SANS texte : fond noir, dégradé orange/teal, logo, forme géométrique)
// uploadé une fois dans la Media Library Cloudinary. Si renseigné, le visuel = CE gabarit + l'accroche
// incrustée par-dessus (aucune illustration IA générée). Comme c'est un asset STOCKÉ, sa livraison ne
// dépend NI du réglage "Fetched URL" NI d'un upload preset -> ça marche même quand tout le reste est
// bloqué. Laisser le placeholder = mode illustration IA (Pollinations) en repli.
const BRAND_TEMPLATE_PUBLIC_ID = "REPLACE_WITH_BRAND_TEMPLATE_PUBLIC_ID";
// Couleurs de marque Nuklear (utilisées pour la plaque de contraste et le badge de catégorie).
const BRAND_DARK = "040404";     // fond
const BRAND_ORANGE = "E23013";   // accent primaire
const BRAND_TEAL = "0E96A8";     // accent secondaire
const BRAND_SLOGAN = "Because what we do is mindblowing"; // slogan de marque, incrusté en bas-centre
// ⚙️ Mode illustration IA (Pollinations). DÉSACTIVÉ par défaut : le tier-gratuit incruste de FAUX
// textes/objets DANS l'image (coeurs, mots parasites, cadrages imprévisibles) -> résultats
// inpubliables. Le rendu par défaut est un POSTER DE MARQUE déterministe (assets stockés, zéro IA).
// Ne repasser à true QU'AVEC une source d'image fiable (ex: photos de marque stockées dans Cloudinary).
const ENABLE_AI_ILLUSTRATION = false;
// 📷 Banque de PHOTOS RÉELLES (Pexels, gratuit) pour ILLUSTRER l'idée SANS IA -> aucune image
// inventée, aucun faux texte incrusté. Crée une clé gratuite sur https://www.pexels.com/api/
// et colle-la ici. Laissé sur le placeholder = bascule propre sur le poster de marque déterministe.
const PEXELS_KEY = "mc14xFpLtRxzvgx7AxNAM2q1A12S4FGNjD7PvfwUaKm3z1nqdIsaflYc";
const COMPETITOR_CACHE_TTL_MS = 24 * 60 * 60 * 1000; // 24h -- les concurrents ne changent pas d'un message à l'autre

const item = $input.first().json;
const { sender, command, platform, freeText, state } = item;

const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
staticData.competitorsCache = staticData.competitorsCache || {};

// ============================================================================
// Helpers réseau (this.helpers.httpRequest -- natif n8n Code node).
// Un seul retry après échec réseau transitoire : Tavily/Ollama Cloud peuvent
// avoir des blips passagers, un retry évite qu'un message WhatsApp entier
// échoue pour un simple timeout isolé.
// ============================================================================
async function httpRequestWithRetry(opts, retries) {
  try {
    return await this.helpers.httpRequest(opts);
  } catch (e) {
    if (retries > 0) {
      await new Promise(r => setTimeout(r, 500));
      return httpRequestWithRetry.call(this, opts, retries - 1);
    }
    throw e;
  }
}

async function tavilySearch(query, count) {
  try {
    const res = await httpRequestWithRetry.call(this, {
      method: "POST",
      url: "https://api.tavily.com/search",
      headers: { Authorization: `Bearer ${TAVILY_KEY}`, "Content-Type": "application/json" },
      body: { query, max_results: count },
      json: true,
      timeout: 15000,
    }, 1);
    return ((res && res.results) || []).map(r => ({ title: r.title, url: r.url, snippet: r.content }));
  } catch (e) { return []; }
}

// Recherche une PHOTO RÉELLE (Pexels) qui illustre l'idée. Renvoie une URL d'image directe (jpg) ou
// null. Orientation portrait pour coller au format 4:5. On pioche au hasard parmi les résultats pour
// varier le visuel d'une génération à l'autre (Math.random est OK dans un Code node n8n).
async function pexelsSearchPhoto(query) {
  if (!PEXELS_KEY || PEXELS_KEY.indexOf("REPLACE_WITH") !== -1) return null;
  const pick = async (q) => {
    try {
      const res = await httpRequestWithRetry.call(this, {
        method: "GET",
        url: `https://api.pexels.com/v1/search?query=${encodeURIComponent(q)}&orientation=portrait&per_page=12&size=large`,
        headers: { Authorization: PEXELS_KEY },
        json: true,
        timeout: 15000,
      }, 1);
      const photos = (res && res.photos) || [];
      if (!photos.length) return null;
      const p = photos[Math.floor(Math.random() * photos.length)];
      return (p && p.src && (p.src.portrait || p.src.large2x || p.src.large || p.src.original)) || null;
    } catch (e) { return null; }
  };
  // 1) requête riche (scène décrite par le LLM) ; 2) repli générique si aucun résultat.
  const short = String(query || "").split(/\s+/).slice(0, 6).join(" ").trim();
  return (await pick.call(this, short || "business marketing")) || (await pick.call(this, "modern business marketing office team"));
}

function extractDomain(url) {
  if (!url || url.indexOf("://") === -1) return "";
  return url.split("://")[1].split("/")[0].replace(/^www\./, "");
}

// Plafond de collecte INTERNE (10), indépendant du maxResults de chaque appelant : synthesizeIdea
// demande 8, le handler "news" en demande 5 -- si on mettait en cache une liste tronquée à la
// taille du PREMIER appelant, un appel suivant qui en demande davantage serait silencieusement
// à court de résultats. On collecte toujours large, on tronque à la sortie selon l'appelant.
const COMPETITOR_COLLECT_CAP = 10;

async function discoverCompetitorsUncached(positioning) {
  const queries = [
    `agences concurrentes de ${positioning} Madagascar OR Afrique OR France`,
    `"${positioning}" alternative agency 2026`,
  ];
  let hits = [];
  for (const q of queries) hits = hits.concat(await tavilySearch.call(this, q, 10));
  const seen = new Set(); const profiles = [];
  for (const h of hits) {
    const domain = extractDomain(h.url);
    if (!domain || seen.has(domain) || domain.indexOf("nuklear") !== -1) continue;
    seen.add(domain);
    profiles.push({ name: h.title || domain, domain, snippet: h.snippet || "" });
    if (profiles.length >= COMPETITOR_COLLECT_CAP) break;
  }
  return profiles;
}

// Cache 24h : la découverte de concurrents coûte 2 requêtes Tavily -- sans cache, CHAQUE
// commande gen_image/gen_video/news relance cette découverte, épuisant vite le quota gratuit
// mensuel partagé par toute l'équipe (1000 req/mois Tavily).
async function discoverCompetitors(positioning, maxResults) {
  const cached = staticData.competitorsCache[positioning];
  if (cached && (Date.now() - cached.ts) < COMPETITOR_CACHE_TTL_MS) {
    return cached.data.slice(0, maxResults);
  }
  const data = await discoverCompetitorsUncached.call(this, positioning);
  staticData.competitorsCache[positioning] = { ts: Date.now(), data };
  return data.slice(0, maxResults);
}

async function ollamaComplete(model, system, user, jsonMode) {
  const payload = {
    model,
    messages: [{ role: "system", content: system }, { role: "user", content: user }],
    stream: false,
    options: { temperature: 0.6 }, // grounding réduit vs 0.85 -- moins d'accroches "hors-sol"/incohérentes
  };
  if (jsonMode) payload.format = "json";
  const res = await httpRequestWithRetry.call(this, {
    method: "POST",
    url: "https://ollama.com/api/chat",
    headers: { Authorization: `Bearer ${OLLAMA_KEY}` },
    body: payload,
    json: true,
    timeout: 120000,
  }, 1);
  return res.message.content;
}

function extractJson(rawText) {
  const fenced = rawText.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/);
  const candidate = fenced ? fenced[1] : rawText;
  try { return JSON.parse(candidate); } catch (e) {
    const brace = candidate.match(/\{[\s\S]*\}/);
    if (brace) return JSON.parse(brace[0]);
    throw e;
  }
}

async function completeJson(system, user) {
  try {
    const rawText = await ollamaComplete.call(this, OLLAMA_MODEL, system, user, true);
    return extractJson(rawText);
  } catch (e) {
    try {
      const rawText = await ollamaComplete.call(this, OLLAMA_FALLBACK_MODEL, system, user, true);
      return extractJson(rawText);
    } catch (e2) { return null; }
  }
}

function safeFloat(v, def) {
  const f = parseFloat(v);
  return Number.isFinite(f) ? f : def;
}

// ============================================================================
// Synthèse d'idée virale (LLM avec repli heuristique déterministe -- jamais
// d'échec silencieux : si Ollama tombe, une idée cohérente sort quand même).
// ============================================================================
async function synthesizeIdea(platformArg, hint, previousIdea, forcedCategory) {
  const competitors = await discoverCompetitors.call(this, NUKLEAR_POSITIONING, 8);
  const trendHits = await tavilySearch.call(this, `contenu viral marketing agence ${platformArg} tendance 2026 humour`, 15);
  let competitorHits = [];
  for (const c of competitors.slice(0, 5)) {
    competitorHits = competitorHits.concat(await tavilySearch.call(this, `site:${c.domain} ${platformArg}`, 3));
  }

  let system = `Tu es directeur artistique ET copywriter de Nuklear (agence marketing/growth/SEO). Ton de marque : ${BRAND_VOICE}. Tu conçois UN visuel social VIRAL, digne d'un grand designer, prêt à publier. L'idée doit être CLAIRE, SIMPLE et INTÉRESSANTE : un angle fort compréhensible en 2 secondes, tiré des mécaniques les plus virales (astuce contre-intuitive, erreur #1 courante, secret/coulisses, chiffre choc, avant/après, mythe vs réalité, "personne ne te dit que..."). Réponds UNIQUEMENT en JSON avec EXACTEMENT ces clés :
- "hook" : l'accroche AFFICHÉE sur le visuel, EN FRANÇAIS PARFAIT (zéro faute), courte et percutante, ≤ 10 mots.
- "kicker" : 1 à 3 MOTS-CLÉS EN FRANÇAIS EN MAJUSCULES (le thème, ex: "SEO LOCAL", "ERREUR #1", "ASTUCE PRO"). Étiquette courte.
- "caption" : la LÉGENDE du post, EN FRANÇAIS, 1 à 3 phrases, ton Nuklear (simple, drôle, amical MAIS pro), qui développe l'idée et invite à agir/commenter. 1 emoji max, à la fin.
- "hashtags" : un tableau de 6 à 9 hashtags PERTINENTS et POPULAIRES (mélange large + niche marketing/SEO/réseaux sociaux), en minuscules, sans espace, chacun commençant par #.
- "visual_subject" : EN ANGLAIS, une SCÈNE riche, concrète et cinématographique qui illustre l'idée (peut inclure des PERSONNES RÉALISTES, un décor, une situation ; JAMAIS une icône plate). Ex: "a focused young entrepreneur working late at a glowing laptop in a cozy creative studio". AUCUN texte dans la description.
- "visual_subject_before" / "visual_subject_after" : UNIQUEMENT si category="avant_apres" -- EN
  ANGLAIS, DEUX scènes concrètes et cinématographiques montrant l'état "avant" (le problème) et
  l'état "après" (le résultat), MAIS avec le MÊME décor/personnage/contexte de base -- seul l'état
  change (ex: "a cluttered messy desk with old paperwork" / "the same desk, now clean and organized
  with a laptop"). PAS deux scènes sans rapport. Sinon, laisser vide.
- "visual_subjects" : UNIQUEMENT si category="collection" -- un TABLEAU de 4 scènes EN ANGLAIS, concrètes et DISTINCTES (chacune illustre un élément différent), MAIS COHÉRENTES ENTRE ELLES : même
  décor/équipe/ambiance/lumière d'une scène à l'autre (ex: le même bureau, la même équipe, à des
  moments différents), PAS 4 scènes sans rapport -- pour que les 4 photos se ressemblent visuellement
  une fois assemblées. Sinon, laisser vide ([]).
- "body_lines" : UNIQUEMENT si category="annonce" -- un TABLEAU de 2 à 4 lignes COURTES (≤ 60
  caractères chacune) EN FRANÇAIS, les informations factuelles à communiquer (ex: date, lieu, détail
  pratique, bénéfice clé). Sinon, laisser vide ([]).
- "visual_style" : EN ANGLAIS, exactement l'un de : "cinematic photograph", "modern 3D render", "editorial digital illustration".
- "tone" : EN FRANÇAIS (ex: "humoristique", "inspirant", "expert").
- "category" : réfléchis activement aux QUATRE options ci-dessous avant de choisir -- ne choisis PAS
  automatiquement la première par habitude, chacune est aussi valide que les autres selon l'idée :
  * "astuce" : UN conseil/erreur/mythe/chiffre choc, un seul visuel + une photo.
  * "collection" : PLUSIEURS éléments/services/exemples à présenter ensemble (l'idée liste ou compare
    plusieurs choses -- ex: "3 astuces pour...", "nos services", "les erreurs les plus courantes").
  * "avant_apres" : une transformation/un résultat avant vs après (l'idée décrit un changement dans le
    temps, un état "avant" et un état "après" distincts -- ex: "de 0 à 40 leads", "avant/après refonte").
  * "annonce" : une ANNONCE avec PLUSIEURS informations factuelles à communiquer (événement, ouverture,
    changement, mise à jour, offre d'emploi générale...) -- choisis ce type dès que l'idée a besoin de
    plusieurs points détaillés (date, lieu, condition...) plutôt qu'une seule accroche courte.
  Écris EXACTEMENT l'un de ces 4 mots, en minuscules, SANS accent, SANS espace : astuce / collection /
  avant_apres / annonce (underscore, pas de tiret ni d'espace pour avant_apres).
- "confidence" : nombre 0 à 1.

RÈGLE ABSOLUE : l'accroche ET la légende doivent toujours être CLAIRES et SIGNIFIANTES pour un public
marketing/SEO -- JAMAIS une image ou une phrase absurde/surréaliste sans lien logique avec un vrai sujet
(ex à NE JAMAIS faire : "Logo sur la tête", ou toute juxtaposition bizarre de mots qui ne veut rien dire).
Chaque idée doit pouvoir se résumer en une phrase compréhensible par un humain en 2 secondes.
Exemples d'accroches VALIDES (ton, longueur, clarté à respecter) :
- "L'erreur SEO n°1 : ignorer la vitesse de chargement"
- "80% des clics restent sur la première page Google"
- "Un site sans bouton d'action, c'est un vendeur muet"
Exemples INVALIDES (à ne jamais produire, trop vagues/absurdes/fragmentaires) :
- "Logo sur la tête", "Marketing bizarre", "Astuce", "SEO ?!"`;
  if (previousIdea) system += " Une idée a DÉJÀ été proposée, l'équipe demande un AJUSTEMENT -- garde le même angle sauf si la remarque dit le contraire.";
  // Commande FORCÉE (gen collection / gen avant apres / gen annonce) : la catégorie est déjà connue,
  // pas besoin de la déduire -- mais il faut prévenir le LLM pour qu'il remplisse les champs
  // spécifiques à CETTE catégorie (visual_subjects / visual_subject_before+after / body_lines),
  // sinon ils restent vides et le rendu utilise un repli générique moins riche.
  if (forcedCategory) system += ` IMPORTANT : category DOIT être exactement "${forcedCategory}" -- remplis bien les champs spécifiques à cette catégorie en conséquence.`;

  const trends = trendHits.slice(0, 12).map(h => `- ${h.title}: ${h.snippet}`).join("\n");
  const comps = competitorHits.slice(0, 10).map(h => `- ${h.title}: ${h.snippet}`).join("\n");
  let previousBlock = "";
  if (previousIdea) previousBlock = `\nIdée précédemment proposée (à AJUSTER) :\n- Accroche: ${previousIdea.hook}\n- Concept: ${previousIdea.visual_concept}\n- Ton: ${previousIdea.tone}\n`;
  const user = `Plateforme cible : ${platformArg}\nConsigne équipe : ${hint || "(aucune)"}\n${previousBlock}\nTendances:\n${trends || "(rien)"}\n\nConcurrents:\n${comps || "(rien)"}\n\nPropose la meilleure idée.`;

  const sources = [...trendHits, ...competitorHits].map(h => h.url).filter(Boolean).slice(0, 5);
  const DEFAULT_TAGS = ["#marketingdigital", "#reseauxsociaux", "#growthhacking", "#seo", "#communitymanager", "#contentmarketing", "#nuklear"];

  function buildIdeaFromData(data) {
    if (!data) return null;
    return {
      hook: String(data.hook || "").trim(),
      kicker: String(data.kicker || data.tone || "NUKLEAR").toUpperCase().slice(0, 26),
      caption: String(data.caption || "").trim(),
      hashtags: cleanHashtags(data.hashtags, DEFAULT_TAGS),
      visual_subject: String(data.visual_subject || data.illustration_subject || "").trim(),
      visual_style: String(data.visual_style || "editorial digital illustration"),
      visual_concept: String(data.visual_concept || data.visual_subject || ""),
      format: String(data.format || "post"),
      tone: String(data.tone || "humoristique"),
      category: normalizeCategory(data.category),
      visual_subject_before: String(data.visual_subject_before || "").trim(),
      visual_subject_after: String(data.visual_subject_after || "").trim(),
      visual_subjects: Array.isArray(data.visual_subjects) ? data.visual_subjects.map(s => String(s || "").trim()).filter(Boolean).slice(0, 4) : [],
      body_lines: Array.isArray(data.body_lines) ? data.body_lines.map(s => String(s || "").trim()).filter(Boolean).slice(0, 4) : [],
      inspired_by: sources,
      confidence: safeFloat(data.confidence, 0.8),
    };
  }

  // ============================================================================
  // GARDE-FOU QUALITÉ : une idée vide, trop fragmentaire, absurde (simple écho du
  // kicker) ou sans légende ne part JAMAIS en publication. Un seul essai
  // supplémentaire avec instruction corrective si l'idée échoue le contrôle ;
  // sinon repli sur le CATALOGUE CURATED (jamais du texte scrapé au hasard).
  // ============================================================================
  let idea = buildIdeaFromData(await completeJson.call(this, system, user));
  if (!idea || isWeakIdea(idea)) {
    const correctiveSystem = system + "\n\nATTENTION : ta précédente proposition était trop vague, trop courte, ou incohérente (accroche absurde/sans lien clair avec un vrai sujet marketing/SEO, ou légende manquante). Cette fois, propose une accroche COMPLÈTE (au moins 4-5 mots) sur un VRAI angle marketing/SEO reconnaissable, et une légende développée, distincte de l'accroche.";
    const retryIdea = buildIdeaFromData(await completeJson.call(this, correctiveSystem, user));
    idea = (retryIdea && !isWeakIdea(retryIdea)) ? retryIdea : null;
  }
  if (idea) return idea;

  if (previousIdea) {
    return {
      hook: previousIdea.hook,
      kicker: previousIdea.kicker || "NUKLEAR",
      caption: previousIdea.caption || `${previousIdea.hook} — on t'explique. 🚀`,
      hashtags: (previousIdea.hashtags && previousIdea.hashtags.length) ? previousIdea.hashtags : DEFAULT_TAGS,
      visual_subject: previousIdea.visual_subject || "a modern minimal marketing scene",
      visual_style: previousIdea.visual_style || "editorial digital illustration",
      visual_concept: hint ? `${previousIdea.visual_concept} — ajustement demandé: ${hint}` : previousIdea.visual_concept,
      format: previousIdea.format, tone: previousIdea.tone,
      category: normalizeCategory(previousIdea.category),
      inspired_by: sources.length ? sources : previousIdea.inspired_by, confidence: 0.65,
    };
  }
  // LLM indisponible ou toujours incohérent après retry : on NE renvoie JAMAIS un titre scrapé au
  // hasard (source #1 des idées qui "ne veulent rien dire"). On pioche dans un catalogue d'idées
  // marketing/SEO écrites à la main, toujours claires, toujours publiables.
  return pickCuratedFallback(platformArg, hint, sources, DEFAULT_TAGS);
}

// Détecte une idée FAIBLE (vide, fragmentaire, absurde ou sous-déterminée) -- contrôle purement
// local (aucun appel réseau) déclenché après CHAQUE synthèse LLM, avant qu'une idée parte en
// publication. Volontairement généraliste (pas calé sur un cas précis) pour couvrir les principales
// classes d'échec observées : accroche vide/tronquée, simple écho du kicker, légende manquante ou
// dupliquée, sujet visuel resté sur le repli générique interne (signe que le LLM n'a rien fourni).
// Normalise la catégorie renvoyée par le LLM (ou par une idée précédente) sur les 3 valeurs connues.
// Toute valeur inattendue retombe sur "astuce" (le template le plus simple/robuste) plutôt que de
// planter ou de router vers un builder inexistant.
// Normalisation TOLÉRANTE : un petit modèle LLM n'écrit pas toujours "avant_apres" au caractère près
// (accents, tirets, espaces au lieu d'underscore sont naturels en français -- ex "avant-après",
// "avant après", "Avant/Après"). Une comparaison stricte (===) faisait silencieusement retomber TOUTE
// variante orthographique sur "astuce", donnant l'impression que seules des astuces étaient générées.
// On normalise (accents retirés, séparateurs uniformisés) AVANT de comparer.
function normalizeCategory(cat) {
  const c = String(cat || "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // retire les accents (é -> e, etc.)
    .trim()
    .replace(/[\s\-\/]+/g, "_"); // espaces/tirets/slash -> underscore
  if (c === "collection") return "collection";
  if (c === "avant_apres" || c === "avantapres") return "avant_apres";
  if (c === "annonce") return "annonce";
  return "astuce";
}

function isWeakIdea(idea) {
  const hook = String(idea.hook || "").trim();
  const words = hook.split(/\s+/).filter(Boolean);
  if (!hook || words.length < 3 || hook.length > 90) return true;
  if (idea.kicker && hook.toLowerCase() === String(idea.kicker).toLowerCase()) return true;
  const caption = String(idea.caption || "").trim();
  if (!caption || caption.length < 15 || caption.toLowerCase() === hook.toLowerCase()) return true;
  const subject = String(idea.visual_subject || "").trim().toLowerCase();
  if (!subject || subject === "a modern minimal marketing scene") return true;
  // Une accroche qui se termine par un nombre ISOLÉ ("... pour nos 4") ressemble fortement à une
  // énumération tronquée (le nom qui devait suivre le chiffre a disparu) -- repéré sur un rendu réel
  // (catégorie collection : "Un seul visuel pour nos 4" au lieu de "... nos 4 services").
  if (/\b\d+$/.test(hook.trim())) return true;
  return false;
}

