// Choisit une idée du catalogue -- essaie de matcher les mots (>3 lettres) de la consigne équipe
// (hint) contre les accroches disponibles pour rester pertinent, sinon pioche au hasard.
function pickCuratedFallback(platformArg, hint, sources, DEFAULT_TAGS) {
  const hintWords = String(hint || "").toLowerCase().split(/\s+/).filter(w => w.length > 3);
  let pool = CURATED_FALLBACK_IDEAS;
  if (hintWords.length) {
    const matched = pool.filter(c => hintWords.some(w => c.hook.toLowerCase().includes(w)));
    if (matched.length) pool = matched;
  }
  const pick = pool[Math.floor(Math.random() * pool.length)];
  return {
    hook: pick.hook, kicker: pick.kicker, caption: pick.caption, hashtags: DEFAULT_TAGS,
    visual_subject: pick.visual_subject, visual_style: "editorial digital illustration",
    visual_concept: `Scène marketing, ton ${BRAND_VOICE}, format ${platformArg}, angle: ${pick.hook}`,
    format: "post", tone: pick.tone, category: "astuce", inspired_by: sources, confidence: 0.7,
  };
}

// Nettoie/normalise les hashtags renvoyés par le LLM : force le "#", retire espaces et caractères
// exotiques, dédoublonne, plafonne à 9. Repli sur un jeu par défaut si vide.
function cleanHashtags(arr, fallback) {
  if (!Array.isArray(arr)) return fallback;
  const seen = new Set(); const out = [];
  for (const raw of arr) {
    let h = String(raw).trim().replace(/^#+/, "").replace(/\s+/g, "").replace(/[^0-9A-Za-zÀ-ÿ_]/g, "");
    if (h.length < 2) continue;
    h = "#" + h.toLowerCase();
    if (!seen.has(h)) { seen.add(h); out.push(h); }
    if (out.length >= 9) break;
  }
  return out.length ? out : fallback;
}

function formatIdea(idea, platformArg) {
  const sources = idea.inspired_by.slice(0, 2).map(s => `• ${s}`).join("\n") || "• (analyse tendances en cours)";
  const tags = (idea.hashtags && idea.hashtags.length) ? idea.hashtags.slice(0, 6).join(" ") : "";
  return `💡 *Idée ${platformArg}* (confiance ${Math.round(idea.confidence * 100)}%)\n\n*Accroche:* ${idea.hook}\n*Légende:* ${idea.caption}\n${tags ? "*Hashtags:* " + tags + "\n" : ""}*Visuel:* ${idea.visual_style}, ${idea.visual_subject}\n\n_Inspiré de:_\n${sources}\n\n👉 *ok* pour générer · *encore* pour une autre · *affine: ...* pour ajuster.`;
}

// ============================================================================
// Génération d'image : Pollinations (base) -> Cloudinary /image/fetch/ (logo +
// texte "zéro faute garanti" + finition), tout en une URL. Aucune image
// n'est manipulée dans n8n -- seule une chaîne de caractères est construite.
// ============================================================================
function wrapCaption(text, maxCharsPerLine) {
  const words = text.split(/\s+/);
  const lines = []; let cur = words[0] || "";
  for (const w of words.slice(1)) {
    if ((cur + " " + w).length <= maxCharsPerLine) cur += " " + w; else { lines.push(cur); cur = w; }
  }
  lines.push(cur);
  return lines;
}

// Retire emojis + symboles que Cloudinary ne sait PAS graver dans un calque l_text: (ils
// ressortent en carrés/vides, voire cassent le rendu). Ils restent dans la légende WhatsApp
// (texte natif, toujours correct), juste pas incrustés dans l'image. Cas réel observé en prod :
// une accroche "... SANS ACCROCHE = 🍕" -- l'emoji n'a rien à faire gravé dans le visuel.
function stripForOverlay(s) {
  return String(s)
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{200D}\u{20E3}]/gu, "")
    .replace(/\s{2,}/g, " ")
    .replace(/\s*[=:+\-]\s*$/, "") // enlève un séparateur resté seul après suppression d'un emoji final
    .trim();
}

// Encode le texte pour un paramètre l_text:. On encode une fois, puis on ré-encode UNIQUEMENT les
// séparateurs de transformation Cloudinary (virgule "," et slash "/") -> %252C / %252F, conformément
// à la doc officielle. (Ré-encoder toute la ligne rendrait espaces/accents illisibles si le CDN ne
// décode qu'une fois.) Une accroche vide après nettoyage tombe sur "Nuklear" pour ne jamais produire
// un l_text: vide (que Cloudinary rejette).
// Retour à la ligne plus LARGE, pour les titres compacts en bandeau (60pt) -- encodeHeadline (16
// caractères/ligne) est calé sur le grand titre plein-cadre du poster (78pt) ; réutilisé tel quel à
// 60pt, il force des retours à la ligne inutiles qui ne tenaient pas dans une boîte plus compacte
// (cause du texte qui semblait tronqué sur la collection/avant-après).
function encodeHeadlineWide(hook) {
  const cleaned = stripForOverlay(hook) || "Nuklear";
  const caption = cleaned.length > 160 ? cleaned.slice(0, 159) + "…" : cleaned;
  const lines = wrapCaption(caption, 24).slice(0, 3);
  return lines.map(l => encodeURIComponent(l).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F")).join("%0A");
}

function encodeOverlayText(hook) {
  const cleaned = stripForOverlay(hook) || "Nuklear";
  const caption = cleaned.length > 220 ? cleaned.slice(0, 219) + "…" : cleaned;
  const lines = wrapCaption(caption, 28).slice(0, 4);
  return lines.map(l => encodeURIComponent(l).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F")).join("%0A");
}

// Chaîne de transformations commune au FETCH et à l'UPLOAD : plaque de fond + logo (optionnel) +
// texte (optionnel) + finition. Un public_id de logo rangé dans un dossier ("nuklear/logo") voit
// ses "/" remplacés par ":" (sinon le "/" casse le découpage de l'URL).
function overlayTransforms(withLogo, textLayer) {
  const width = 1080, height = 1350;
  const logoLayerId = LOGO_PUBLIC_ID.replace(/\//g, ":");
  const parts = [`c_pad,w_${width},h_${height},b_rgb:040404`];
  if (withLogo) parts.push(`l_${logoLayerId},g_south_east,x_40,y_40,w_190/fl_layer_apply`);
  if (textLayer) parts.push(`l_text:Arial_54_bold:${textLayer},co_white,c_fit,w_${width - 140},g_south,y_100,b_rgb:040404aa/fl_layer_apply`);
  parts.push(`e_sharpen:60`, `q_auto:best`);
  return parts.join("/");
}

function buildPollinationsUrl(prompt, negativePrompt) {
  const width = 1080, height = 1350;
  const fullPrompt = `${prompt} | avoid: ${negativePrompt}`;
  return `https://image.pollinations.ai/prompt/${encodeURIComponent(fullPrompt)}?width=${width}&height=${height}&nologo=true&model=flux`;
}

// Montage par FETCH : Cloudinary va chercher l'URL Pollinations via /image/fetch/. FRAGILE -- dépend
// du réglage compte "Fetched URL", DÉSACTIVÉ par défaut sur les comptes Cloudinary récents, ce qui
// fait échouer TOUTE URL /image/fetch/ avec une 400 (y compris sans overlay). Gardé comme repli au
// cas où le compte l'autorise, mais n'est plus le chemin principal.
function buildFetchTiers(pollinationsUrl, hook) {
  const t = encodeOverlayText(hook);
  const src = encodeURIComponent(pollinationsUrl);
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/fetch`;
  return [
    { label: "fetch logo+texte", url: `${root}/${overlayTransforms(true, t)}/${src}` },
    { label: "fetch texte seul", url: `${root}/${overlayTransforms(false, t)}/${src}` },
    { label: "fetch logo seul", url: `${root}/${overlayTransforms(true, null)}/${src}` },
  ];
}

// Montage par UPLOAD : Cloudinary a déjà téléchargé et STOCKÉ l'image (via l'upload preset). Les
// transformations s'appliquent alors à un asset stocké normal (/image/upload/), ce qui NE dépend
// PAS du réglage "Fetched URL" -> fonctionne même quand /image/fetch/ est bloqué. C'est
// l'alternative sûre au point faible n°1 (dépendance à un réglage de sécurité caché).
function buildUploadTiers(publicId, hook) {
  const t = encodeOverlayText(hook);
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  return [
    { label: "upload logo+texte", url: `${root}/${overlayTransforms(true, t)}/${publicId}` },
    { label: "upload texte seul", url: `${root}/${overlayTransforms(false, t)}/${publicId}` },
    { label: "upload logo seul", url: `${root}/${overlayTransforms(true, null)}/${publicId}` },
  ];
}

// Prompt pour une ILLUSTRATION de marque (fond du visuel riche) : style flat vector éditorial,
// palette Nuklear (noir + orange + teal), UN concept clair lié à l'idée, zone sombre réservée en bas
// pour le texte, aucun texte/personnage. Donne des illustrations différentes selon le contenu.
function buildIllustrationPrompt(idea) {
  // Visuel RICHE plein cadre (scène évocatrice, personnes réalistes possibles) et non plus une
  // petite icône plate sur fond vide. On garde le SUJET en anglais (flux ajoute du faux texte si on
  // lui donne l'accroche FR) + on impose un tiers inférieur SOMBRE pour y intégrer le titre sans
  // plaque. Négatifs stricts contre tout texte, mais PERSONNES autorisées (juste pas déformées).
  const subject = (idea.visual_subject && idea.visual_subject.trim()) || "a modern minimal marketing scene";
  const style = (idea.visual_style && idea.visual_style.trim()) || "editorial digital illustration";
  const p = `${style} of ${subject}. Professional editorial quality worthy of a top designer, rich detailed composition that FILLS the entire frame, dramatic moody lighting, subtle brand accents of orange (#E23013) and teal (#0E96A8), deep dark tones, a darker gradient across the lower third leaving clean space for a headline. Cohesive color grading, sharp, high quality, trending on Behance. No text, no words, no letters, no logo, no watermark.`;
  const neg = "text, words, letters, numbers, typography, captions, labels, ui, buttons, poster layout, mockup, watermark, signature, logo, frame, border, low quality, blurry, deformed, disfigured, extra limbs, extra fingers, mutated hands, ugly";
  return buildPollinationsUrl(p, neg);
}

// Montage RICHE, style ÉDITORIAL, sur une illustration uploadée (asset stocké). Le visuel plein cadre
// devient l'environnement ; le texte s'y intègre SANS plaque noire : on assombrit dégressivement le
// bas (dégradé sombre baké par Cloudinary) pour la lisibilité, on ajoute une OMBRE portée au titre,
// et une accroche colorée (kicker orange) crée la hiérarchie -- comme un vrai poster de designer.
// Transformation d'un asset stocké -> aucune dépendance à "Fetched URL".
// Calque LOGO complet : icône [N] (MINILOGO) + wordmark (LOGO), toujours recomposés à partir de DEUX
// assets STOCKÉS sur le même cloud -- aucune dépendance externe. Hauteur commune -> alignement
// automatique. L'icône est supposée à peu près carrée (comme sur la maquette de référence) ; si son
// aspect réel diffère, ajuster GAP_RATIO est le seul réglage nécessaire.
// Socle du visuel, commun à tous les rendus. Renvoie l'asset de BASE et sa transformation de canevas.
// - Si le FOND DÉGRADÉ est configuré : c'est lui la base, simplement recadré en 4:5 (g_auto garde la
//   zone la plus intéressante) -> on obtient le dégradé exact de la maquette, sans aucun calcul de
//   halo hasardeux (c'est ce qui avait échoué avec les lueurs générées).
// - Sinon : comportement actuel validé (le logo sert de base, aplati en noir uni).
function canvasBase(W, H, bgId) {
  if (bgId) return { base: bgId, canvas: `c_fill,w_${W},h_${H},g_auto` };
  return { base: LOGO_PUBLIC_ID, canvas: `c_fill,w_${W},h_${H},e_colorize:100,co_rgb:${BRAND_DARK},b_rgb:${BRAND_DARK}` };
}

// Résout le public_id du FOND DÉGRADÉ, en le mettant en cache : (1) public_id explicite si fourni,
// (2) sinon tirage au sort dans BRAND_BG_SOURCES + upload unique par source, mémorisé pour les
// exécutions suivantes, (3) sinon null -> canevas noir uni (comportement validé). Ne lève jamais : en
// cas d'échec réseau on retombe simplement sur le canevas uni plutôt que de casser la génération.
// Résout un fond depuis UN pool donné (portrait ou paysage), avec cache indépendant par pool
// (cacheKey distinct) -- factorisé pour ne pas dupliquer la logique de rotation/repli entre formats.
async function resolveBackgroundFromPool(sources, cacheKey) {
  const valid = sources.filter(u => u && u.indexOf("REPLACE_WITH") === -1);
  if (!valid.length) return null;
  const presetOk = CLOUDINARY_UPLOAD_PRESET && CLOUDINARY_UPLOAD_PRESET.indexOf("REPLACE_WITH") === -1;
  if (!presetOk) return null;
  staticData[cacheKey] = staticData[cacheKey] || {}; // { [sourceUrl]: publicId }
  const cache = staticData[cacheKey];
  const pickUrl = valid[Math.floor(Math.random() * valid.length)];
  if (cache[pickUrl]) return cache[pickUrl];
  try {
    const pid = await cloudinaryUploadFromUrl.call(this, pickUrl);
    if (pid) { cache[pickUrl] = pid; return pid; }
  } catch (e) { /* on retente un fond déjà connu ci-dessous plutôt que d'abandonner tout de suite */ }
  const known = valid.map(u => cache[u]).filter(Boolean);
  if (known.length) return known[Math.floor(Math.random() * known.length)];
  return null;
}

async function resolveBrandBackground() {
  if (BRAND_BG_PUBLIC_ID && BRAND_BG_PUBLIC_ID.indexOf("REPLACE_WITH") === -1) return BRAND_BG_PUBLIC_ID;
  return resolveBackgroundFromPool.call(this, BRAND_BG_SOURCES, "brandBgCache");
}

async function resolveLandscapeBackground() {
  return resolveBackgroundFromPool.call(this, BRAND_BG_SOURCES_LANDSCAPE, "brandBgCacheLandscape");
}

function logoLockupLayers(Mx, My, h) {
  const GAP = Math.round(h * 0.22);
  const miniId = MINILOGO_PUBLIC_ID.replace(/\//g, ":");
  const wordId = LOGO_PUBLIC_ID.replace(/\//g, ":");
  const mini = `l_${miniId},e_colorize:100,co_white,c_scale,h_${h}/fl_layer_apply,g_north_west,x_${Mx},y_${My}`;
  const word = `l_${wordId},e_colorize:100,co_white,c_scale,h_${h}/fl_layer_apply,g_north_west,x_${Mx + h + GAP},y_${My}`;
  return [mini, word];
}

// LUEURS de fond façon maquette de marque (dégradé chaud orange qui remonte d'un coin + touche teal
// discrète dans l'autre) : SANS paramètre de dégradé Cloudinary non vérifié -- on réutilise exactement
// la recette déjà PROUVÉE en prod par le canevas (c_fill + e_colorize:100 + b_rgb DE LA MÊME COULEUR =
// aplat 100% opaque et uniforme, quel que soit l'asset source), puis on floute fort (e_blur) et on
// baisse l'opacité (o_) -- deux effets Cloudinary parmi les plus stables/standards qui soient. Bleed
// hors-cadre (gravité de coin + décalage négatif) pour un halo organique, pas un carré net.
function brandGlowLayers() {
  if (!ENABLE_BRAND_GLOW) return [];
  const id = LOGO_PUBLIC_ID.replace(/\//g, ":");
  // UN SEUL effet e_ PAR COMPOSANT (règle Cloudinary ; sa violation était la cause du rectangle plein) :
  // 1er composant = dimensionne le bloc, 2e = l'aplatit en couleur unie (colorize + b_rgb), 3e = floute,
  // 4e = opacité. Le flou adoucit les BORDS du bloc -> halo diffus. Décalage négatif = bleed hors-cadre.
  const warm = `l_${id}/c_fill,w_860,h_860/e_colorize:100,co_rgb:${BRAND_ORANGE}/e_blur:2000/o_55/fl_layer_apply,g_south_west,x_-280,y_-300`;
  const cool = `l_${id}/c_fill,w_580,h_580/e_colorize:100,co_rgb:${BRAND_TEAL}/e_blur:2000/o_26/fl_layer_apply,g_south_east,x_-240,y_-180`;
  return [warm, cool];
}

// Visuel de RECRUTEMENT : format "offre d'emploi", champs saisis PRÉCISÉMENT par l'équipe (jamais
// inventés par le LLM -- fiabilité factuelle exigée : intitulé, contrat, lieu, email). Même socle que
// le poster de marque (canevas + lockup logo), sans photo -- correspond à la maquette de référence.
// Visuel AVANT / APRÈS : DEUX vraies photos côte à côte (split-screen), chacune labellisée. Texte
// (logo, kicker, H1) au-dessus du split, slogan tout en bas -- même socle que les autres templates.
// Marges vérifiées par calcul : bandeau haut se termine à y=400 (40px avant les photos à y=440) ;
// photos 440->1100 (178px de marge avant le slogan à y=1278).
function buildBeforeAfterTiers(beforePid, afterPid, idea, bgId) {
  const W = 1080, H = 1350, M = 72;
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  const { base, canvas } = canvasBase(W, H, bgId);
  const kicker = encodeURIComponent(String(idea.kicker || "AVANT / APRÈS").toUpperCase()).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const t = encodeHeadlineWide(idea.hook);
  const slogan = encodeURIComponent(BRAND_SLOGAN).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const beforeId = String(beforePid).replace(/\//g, ":");
  const afterId = String(afterPid).replace(/\//g, ":");

  // Photos SANS vignette (même correctif que la collection -- l'effet de tache floue/ovale sur des
  // panneaux de cette taille venait de là). PHOTO_Y décalé à 450 pour la boîte de titre agrandie
  // (h_200, voir titleLayer).
  const LEFT_X = 40, RIGHT_X = 560, PW = 480, PH = 650, PHOTO_Y = 450;
  const beforePhoto = `l_${beforeId}/c_fill,w_${PW},h_${PH}/e_brightness:-6/e_contrast:6/fl_layer_apply,g_north_west,x_${LEFT_X},y_${PHOTO_Y}`;
  const afterPhoto = `l_${afterId}/c_fill,w_${PW},h_${PH}/e_brightness:-6/e_contrast:6/fl_layer_apply,g_north_west,x_${RIGHT_X},y_${PHOTO_Y}`;
  // Étiquettes AVANT/APRÈS sur les photos elles-mêmes -- ombre portée pour rester lisibles quel que
  // soit le contenu de la photo à cet endroit précis (même garde-fou que le slogan).
  const beforeLabel = `l_text:Arial_36_bold:${encodeURIComponent("AVANT")},co_rgb:${BRAND_ORANGE},e_shadow:80/fl_layer_apply,g_north_west,x_${LEFT_X + 20},y_${PHOTO_Y + 20}`;
  const afterLabel = `l_text:Arial_36_bold:${encodeURIComponent("APRÈS")},co_rgb:${BRAND_ORANGE},e_shadow:80/fl_layer_apply,g_north_west,x_${RIGHT_X + 20},y_${PHOTO_Y + 20}`;

  const [miniLayer, wordLayer] = logoLockupLayers(M, 52, 84);
  const kickerLayer = `l_text:Arial_44_bold:${kicker},co_rgb:${BRAND_ORANGE}/fl_layer_apply,g_north_west,x_${M + 2},y_170`;
  const titleLayer = `l_text:Arial_60_bold:${t},co_white,c_fit,w_${W - 2 * M},h_200/fl_layer_apply,g_north_west,x_${M},y_230`;
  const sloganLayer = `l_text:Arial_36_bold:${slogan},co_white,e_shadow:90/fl_layer_apply,g_north,y_1278`;
  const finish = "q_auto:best";
  const full = [canvas, beforePhoto, afterPhoto, beforeLabel, afterLabel, miniLayer, wordLayer, kickerLayer, titleLayer, sloganLayer, finish].join("/");
  const noKicker = [canvas, beforePhoto, afterPhoto, beforeLabel, afterLabel, miniLayer, wordLayer, titleLayer, sloganLayer, finish].join("/");
  const bare = [canvas, beforePhoto, afterPhoto, miniLayer, wordLayer, titleLayer, finish].join("/");
  return [
    { label: "avant-après complet", url: `${root}/${full}/${base}` },
    { label: "avant-après sans badge", url: `${root}/${noKicker}/${base}` },
    { label: "avant-après minimal", url: `${root}/${bare}/${base}` },
  ];
}

// Visuel COLLECTION : grille 2x2 de photos réelles distinctes (jusqu'à 4), pour présenter PLUSIEURS
// éléments (services, exemples...) dans un seul visuel. Même bandeau haut (logo+kicker+H1) et slogan
// que les autres templates. Grille calculée : disponible 440->1238 (798px), 2x2 avec 24px d'écart ->
// tuiles de 488x387, la tuile bas-droite finit exactement à 1238 (40px avant le slogan à y_1278).
// GARANTIT toujours 4 sujets de recherche COHÉRENTS (même scène de base + variantes d'angle/moment),
// que le LLM ait rempli visual_subjects ou non. Avant ce garde-fou, une catégorie "collection" mal
// remplie par le LLM (tableau vide/incomplet -- fréquent avec un petit modèle) faisait SILENCIEUSEMENT
// retomber tout le rendu sur le template "astuce" à une seule photo, sans aucun signal visible -- donc
// même quand le LLM classait correctement l'idée en "collection", le résultat ne le reflétait jamais.
// Dériver des variantes d'UNE scène de base est aussi plus cohérent visuellement que 4 scènes
// distinctes inventées séparément par le LLM (même décor/lumière, juste un angle différent).
function deriveCollectionSubjects(idea) {
  if (idea.visual_subjects && idea.visual_subjects.length >= 2) return idea.visual_subjects.slice(0, 4);
  const base = (idea.visual_subject || idea.hook || "modern marketing team at work").trim();
  const variants = ["", ", close-up detail shot", ", wide establishing shot", ", candid moment"];
  return variants.map(v => `${base}${v}`);
}

function buildCollectionTiers(photoPids, idea, bgId) {
  const W = 1080, H = 1350, M = 72;
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  const { base, canvas } = canvasBase(W, H, bgId);
  const kicker = encodeURIComponent(String(idea.kicker || "COLLECTION").toUpperCase()).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const t = encodeHeadlineWide(idea.hook);
  const slogan = encodeURIComponent(BRAND_SLOGAN).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");

  // Grille recalculée pour la boîte de titre agrandie (h_200, voir titleLayer) : 450->1238 dispo
  // (788px), 2x2 avec 24px d'écart -> tuiles 488x382, la dernière finit pile à 1238 (40px avant le
  // slogan). SANS vignette : sur des tuiles de cette taille, la vignette créait un effet de tache
  // floue/ovale au lieu de rectangles nets (repéré sur un rendu réel) -- juste un léger calage
  // colorimétrique (brightness/contrast) pour rester cohérent avec les autres templates.
  const TILE_W = 488, TILE_H = 382, GAP = 24;
  const positions = [
    { x: 40, y: 450 }, { x: 40 + TILE_W + GAP, y: 450 },
    { x: 40, y: 450 + TILE_H + GAP }, { x: 40 + TILE_W + GAP, y: 450 + TILE_H + GAP },
  ];
  const tiles = photoPids.slice(0, 4).map((pid, i) => {
    const id = String(pid).replace(/\//g, ":");
    const p = positions[i];
    return `l_${id}/c_fill,w_${TILE_W},h_${TILE_H}/e_brightness:-4/e_contrast:4/fl_layer_apply,g_north_west,x_${p.x},y_${p.y}`;
  });

  const [miniLayer, wordLayer] = logoLockupLayers(M, 52, 84);
  const kickerLayer = `l_text:Arial_44_bold:${kicker},co_rgb:${BRAND_ORANGE}/fl_layer_apply,g_north_west,x_${M + 2},y_170`;
  const titleLayer = `l_text:Arial_60_bold:${t},co_white,c_fit,w_${W - 2 * M},h_200/fl_layer_apply,g_north_west,x_${M},y_230`;
  const sloganLayer = `l_text:Arial_36_bold:${slogan},co_white,e_shadow:90/fl_layer_apply,g_north,y_1278`;
  const finish = "q_auto:best";
  const full = [canvas, ...tiles, miniLayer, wordLayer, kickerLayer, titleLayer, sloganLayer, finish].join("/");
  const noKicker = [canvas, ...tiles, miniLayer, wordLayer, titleLayer, sloganLayer, finish].join("/");
  const bare = [canvas, ...tiles, miniLayer, wordLayer, titleLayer, finish].join("/");
  return [
    { label: "collection complète", url: `${root}/${full}/${base}` },
    { label: "collection sans badge", url: `${root}/${noKicker}/${base}` },
    { label: "collection minimale", url: `${root}/${bare}/${base}` },
  ];
}

// Visuel ANNONCE, format PAYSAGE (1080x588 -- même ratio que fond3.png, aucun recadrage nécessaire) :
// pour du contenu avec BEAUCOUP de texte à structurer clairement. Colonne gauche = titre, colonne
// droite = jusqu'à 4 lignes de détails -- exploite la largeur, impossible en portrait 4:5. Purement
// textuel (comme le recrutement) : aucune photo, aucune dépendance Pexels, rendu 100% fiable.
function buildAnnonceTiers(idea, bgId) {
  const W = 1080, H = 588, M = 48;
