  const kicker = encodeURIComponent(String(idea.kicker || "ANNONCE").toUpperCase()).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const t = encodeHeadline(idea.hook);
  const bodyText = (idea.body_lines && idea.body_lines.length ? idea.body_lines : ["Plus d'infos à venir."]).join("\n");
  const body = encodeURIComponent(bodyText).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const slogan = encodeURIComponent(BRAND_SLOGAN).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");

  const [miniLayer, wordLayer] = logoLockupLayers(M, 28, 56);
  const kickerLayer = `l_text:Arial_30_bold:${kicker},co_rgb:${BRAND_ORANGE}/fl_layer_apply,g_north_west,x_${M + 2},y_100`;
  // Colonne gauche : titre, borné en largeur (460) pour ne jamais empiéter sur la colonne droite.
  const titleLayer = `l_text:Arial_46_bold:${t},co_white,c_fit,w_460,h_280/fl_layer_apply,g_north_west,x_${M},y_140`;
  // Colonne droite : détails, également bornée -> les deux colonnes ne se touchent jamais quelle que
  // soit la longueur du texte (c_fit rétrécit plutôt que déborder, même filet que les autres templates).
  const bodyLayer = `l_text:Arial_30_bold:${body},co_white,c_fit,w_460,h_350/fl_layer_apply,g_north_west,x_560,y_100`;
  const sloganLayer = `l_text:Arial_24_bold:${slogan},co_white,e_shadow:90/fl_layer_apply,g_south,y_28`;
  const finish = "q_auto:best";
  const full = [canvas, miniLayer, wordLayer, kickerLayer, titleLayer, bodyLayer, sloganLayer, finish].join("/");
  const noSlogan = [canvas, miniLayer, wordLayer, kickerLayer, titleLayer, bodyLayer, finish].join("/");
  const minimal = [canvas, miniLayer, wordLayer, titleLayer, finish].join("/");
  return [
    { label: "annonce complète", url: `${root}/${full}/${base}` },
    { label: "annonce sans slogan", url: `${root}/${noSlogan}/${base}` },
    { label: "annonce minimale", url: `${root}/${minimal}/${base}` },
