    { label: "illustration éditoriale", url: `${root}/${[fillFx, miniLayer, wordLayer, kickerLayer, titleFx, sloganLayer, finish].join("/")}/${publicId}` },
    { label: "illustration + titre", url: `${root}/${[fillFx, miniLayer, wordLayer, titleFx, sloganLayer, finish].join("/")}/${publicId}` },
    { label: "illustration simple", url: `${root}/${[fillPlain, miniLayer, wordLayer, titlePlain, sloganLayer, finish].join("/")}/${publicId}` },
  ];
}

// Montage sur GABARIT DE MARQUE : le fond Nuklear vierge est un asset STOCKÉ ; on incruste juste
// l'accroche par-dessus. Livraison d'un asset stocké -> ne dépend NI de "Fetched URL" NI d'un upload
// preset. C'est le chemin le plus fiable ET le seul qui donne un rendu 100% fidèle à la charte
// (fond, dégradé, logo, forme déjà dans le gabarit). Renvoie [] si aucun gabarit n'est configuré.
function buildTemplateTiers(hook) {
  if (!BRAND_TEMPLATE_PUBLIC_ID || BRAND_TEMPLATE_PUBLIC_ID.indexOf("REPLACE_WITH") !== -1) return [];
  const t = encodeOverlayText(hook);
  const base = BRAND_TEMPLATE_PUBLIC_ID; // asset stocké : un "/" de dossier est OK en fin d'URL
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  // L'accroche en gros, blanc, sur une plaque sombre pour rester lisible quelle que soit la zone du
  // gabarit. Placement par défaut au centre -- affinable précisément une fois le gabarit connu.
  const textLayer = `l_text:Arial_64_bold:${t},co_white,c_fit,w_880,g_center,y_0,b_rgb:${BRAND_DARK}cc`;
  return [
    { label: "gabarit marque + texte", url: `${root}/${textLayer}/fl_layer_apply/q_auto:best/${base}` },
    { label: "gabarit marque nu", url: `${root}/q_auto:best/${base}` }, // au pire : le fond de marque seul
  ];
}

// Encode une accroche pour un GROS titre (typo principale du gabarit) : lignes courtes, jusqu'à 5,
// adaptées à une grande taille de police.
function encodeHeadline(hook) {
  const cleaned = stripForOverlay(hook) || "Nuklear";
  const caption = cleaned.length > 160 ? cleaned.slice(0, 159) + "…" : cleaned;
  const lines = wrapCaption(caption, 16).slice(0, 5);
  return lines.map(l => encodeURIComponent(l).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F")).join("%0A");
}

// GABARIT DE MARQUE SYNTHÉTISÉ (auto-généré, AUCUN asset externe à fournir) : on part du LOGO
// (asset stocké), on le réduit et on le pose en haut à gauche sur un canevas sombre 1080x1350, puis
// on incruste un badge de catégorie (orange), le gros titre (accroche) et un pied de marque orange.
// Comme c'est la transformation d'un asset STOCKÉ, la livraison ne dépend NI de "Fetched URL" NI d'un
// upload preset -> c'est le chemin le plus fiable, et le rendu (fond sombre + typo + logo + accents
// orange) colle à la charte Nuklear, sans aucune illustration IA. Renvoie [] si le logo n'est pas
// configuré (on retombe alors sur l'illustration IA).
// MISE EN PAGE ÉDITORIALE "3 BANDES" sur une PHOTO RÉELLE (asset stocké) : bandeau sombre (logo) /
// FENÊTRE PHOTO plein largeur / pied sombre (kicker orange + H1 + slogan). TOUT le texte est sur du
// NOIR PLEIN -> lisibilité garantie, et la photo reste une fenêtre nette et non obstruée. Aucun
// dégradé/ombre fragile. Base = logo colorisé en canevas sombre (même socle éprouvé que le poster).
function buildPhotoEditorialTiers(photoPublicId, idea, bgId) {
  const W = 1080, H = 1350, M = 72;
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  const { base, canvas } = canvasBase(W, H, bgId); // fond dégradé si dispo, sinon noir uni -- 4:5
  const kicker = encodeURIComponent(String(idea.kicker || "NUKLEAR").toUpperCase()).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const slogan = encodeURIComponent(BRAND_SLOGAN).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const photoLayerId = String(photoPublicId).replace(/\//g, ":");
  // ============================================================================================
  // MISE EN PAGE V2 : texte AU-DESSUS (bandeau haut), PHOTO GRANDE ET IMMERGÉE dessous, slogan tout
  // en bas. Remplace l'ancienne version qui calait un petit cercle pile sur l'anneau d'UN fond.png
  // précis (fragile dès que plusieurs fonds différents entrent en rotation, et jugée trop petite).
  // Ici la photo occupe la majorité du canevas (calcul ci-dessous), avec vignette + grading pour se
  // fondre dans N'IMPORTE quel fond sombre de la même famille, sans dépendre des coordonnées exactes
  // d'un anneau précis -- robuste face à une bibliothèque de fonds qui varie à chaque génération.
  // Marges vérifiées : bandeau (logo+kicker+H1) se termine à y=510 ; photo 565->1225 (55px de marge
  // au-dessus, 53px avant le slogan à y=1278) ; H1 en c_fit (h_280) donc jamais de débordement même
  // si l'accroche est longue -- le texte rétrécit pour tenir, il ne déborde jamais.
  // ============================================================================================
  const t = encodeHeadline(idea.hook);
  const photo = bgId
    ? `l_${photoLayerId}/c_fill,w_660,h_660/r_max/e_brightness:-6/e_contrast:6/e_vignette:35/fl_layer_apply,g_north_west,x_210,y_565`
    : `l_${photoLayerId}/c_fill,w_${W},h_680/e_brightness:-8/e_contrast:6/e_vignette:40/fl_layer_apply,g_north,y_565`;
  const glow = brandGlowLayers(); // [] si désactivée
  const [miniLayer, wordLayer] = logoLockupLayers(M, 52, 84);
  const kickerLayer = `l_text:Arial_44_bold:${kicker},co_rgb:${BRAND_ORANGE}/fl_layer_apply,g_north_west,x_${M + 2},y_170`;
  const titleLayer = `l_text:Arial_66_bold:${t},co_white,c_fit,w_${W - 2 * M},h_280/fl_layer_apply,g_north_west,x_${M},y_230`;
  const sloganLayer = `l_text:Arial_36_bold:${slogan},co_white,e_shadow:90/fl_layer_apply,g_north,y_1278`;
  const finish = "q_auto:best";
  const full = [canvas, photo, ...glow, miniLayer, wordLayer, kickerLayer, titleLayer, sloganLayer, finish].join("/");
  const noKicker = [canvas, photo, ...glow, miniLayer, wordLayer, titleLayer, sloganLayer, finish].join("/");
  // Filet ULTRA-SÛR : mêmes assets, SANS lueur.
  const bare = [canvas, photo, miniLayer, wordLayer, titleLayer, finish].join("/");
  return [
    { label: "photo éditoriale", url: `${root}/${full}/${base}` },
    { label: "photo + titre", url: `${root}/${noKicker}/${base}` },
    { label: "photo simple", url: `${root}/${bare}/${base}` },
  ];
}

function buildBrandCanvasTiers(hook, badge, kickerText, bgId) {
  if (!LOGO_PUBLIC_ID || LOGO_PUBLIC_ID.indexOf("REPLACE_WITH") !== -1) return [];
  const W = 1080, H = 1350;
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  const M = 80; // marge de sécurité commune
  // 1) CANEVAS 4:5 (1080x1350) : fond dégradé de marque si configuré, sinon noir uni (voir canvasBase).
  const { base, canvas } = canvasBase(W, H, bgId);
  // 2) LUEURS de fond (dégradé chaud façon maquette de marque) -- POSÉES AVANT le logo/texte pour
  //    rester en arrière-plan. Voir brandGlowLayers() pour le détail de la technique.
  const glow = brandGlowLayers(); // [] si la lueur est désactivée -> spread = aucun calque ajouté
  // 3) LOGO complet (icône [N] + wordmark), HAUT-GAUCHE, hauteur fixe (h_110) -> bien visible.
  const [miniLayer, wordLayer] = logoLockupLayers(M, M, 110);
  // 4) KICKER = mot-clé en ORANGE de marque, SOUS le logo (la "touche d'orange" sur les mots-clés).
  const kicker = encodeURIComponent(String(kickerText || "NUKLEAR").toUpperCase()).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const kickerLayer = `l_text:Arial_42_bold:${kicker},co_rgb:${BRAND_ORANGE}/fl_layer_apply,g_north_west,x_${M + 2},y_244`;
  // 5) H1 (titre) BLANC, GROS, aligné à gauche, SOUS le kicker (haut-gauche).
  const title = `l_text:Arial_78_bold:${encodeHeadline(hook)},co_white,c_fit,w_${W - 2 * M},h_620/fl_layer_apply,g_north_west,x_${M},y_330`;
  // 6) SLOGAN de marque, BAS-CENTRE, bien visible.
  const slogan = encodeURIComponent(BRAND_SLOGAN).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const sloganLayer = `l_text:Arial_40_bold:${slogan},co_white,e_shadow:90/fl_layer_apply,g_south,y_96`;
  const finish = "q_auto:best";
  const full = [canvas, ...glow, miniLayer, wordLayer, kickerLayer, title, sloganLayer, finish].join("/");
  const noKicker = [canvas, ...glow, miniLayer, wordLayer, title, sloganLayer, finish].join("/");
  // Filet ULTRA-SÛR : mêmes assets, SANS lueur -- si jamais le calque de lueur posait un souci sur un
  // compte Cloudinary particulier, ce cran retombe sur la combinaison la plus proche de l'ancienne
  // version déjà validée en prod (canevas plat + logo + titre).
  const minimal = [canvas, miniLayer, wordLayer, title, finish].join("/");
  return [
    { label: "gabarit auto + badge", url: `${root}/${full}/${base}` },
    { label: "gabarit auto", url: `${root}/${noKicker}/${base}` },
    { label: "gabarit auto minimal", url: `${root}/${minimal}/${base}` },
  ];
}

// Upload UNSIGNED depuis une URL distante : Cloudinary récupère l'image LUI-MÊME côté serveur
// pendant l'upload (indépendant du réglage fetch de livraison). Renvoie le public_id, ou null.
async function cloudinaryUploadFromUrl(sourceUrl) {
  // IMPORTANT : l'API d'upload Cloudinary attend du FORM-urlencoded, PAS du JSON. Envoyer du JSON
  // (json:true) fait échouer l'upload ("Missing required parameter - file"). On envoie donc un corps
  // application/x-www-form-urlencoded et on parse la réponse JSON à la main.
  const body = `file=${encodeURIComponent(sourceUrl)}&upload_preset=${encodeURIComponent(CLOUDINARY_UPLOAD_PRESET)}`;
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD}/image/upload`,
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body,
    json: false,
    timeout: 90000,
  });
  let data = res;
  if (typeof res === "string") { try { data = JSON.parse(res); } catch (e) { data = {}; } }
  return (data && data.public_id) ? data.public_id : null;
}

// Extrait la vraie cause d'un échec httpRequest : Cloudinary la met dans l'en-tête x-cld-error,
// n8n dans e.message ("400 - ...") ou e.response. On la remonte jusqu'au message WhatsApp pour ne
// plus jamais diagnostiquer à l'aveugle.
// Essaie une liste de crans dans l'ordre ; renvoie le PREMIER qui répond 2xx (this.helpers.httpRequest
// -- contexte n8n). Utilisé par "validate" (astuce/collection/avant_apres) ET par la commande
// recrutement -- factorisé pour ne pas dupliquer la logique de repli entre les deux.
async function tryTiers(tiers) {
  const errors = [];
  for (const tier of tiers) {
    try {
      await this.helpers.httpRequest({ method: "GET", url: tier.url, timeout: 30000, json: false });
      return { tier, errors };
    } catch (e) { errors.push(`${tier.label} → ${extractHttpError(e)}`); }
  }
  return { tier: null, errors };
}

function extractHttpError(e) {
  const resp = e && e.response;
  const hdr = (resp && (resp.headers || {})) || {};
  const cld = hdr["x-cld-error"] || hdr["X-Cld-Error"];
  if (cld) return String(cld).slice(0, 200);
  if (e && e.message) return String(e.message).slice(0, 200);
  return String(e).slice(0, 200);
}

// ============================================================================
// Routage par commande.
// ============================================================================
let result = { sender, text: "Commande non reconnue. Tape *aide*.", image_url: null };

if (command === "news") {
  const sectorHits = await tavilySearch.call(this, `actualités ${NUKLEAR_POSITIONING} 2026`, 8);
  const competitors = await discoverCompetitors.call(this, NUKLEAR_POSITIONING, 5);
  let lines = ["📰 *Veille Nuklear*\n"];
  for (const h of sectorHits) lines.push(`📈 secteur — ${h.title}\n${h.url}`);
  for (const c of competitors.slice(0, 5)) {
    const hits = await tavilySearch.call(this, `${c.name} actualité annonce 2026`, 2);
    for (const h of hits) lines.push(`🏢 concurrent — ${h.title}\n${h.url}`);
  }
  result.text = lines.length > 1 ? lines.join("\n\n") : "Aucune actualité pertinente trouvée pour le moment.";
}

else if (command === "gen_video") {
  const idea = await synthesizeIdea.call(this, "reels", freeText, null);
  const concept = "astuce_rapide";
  const beats = [
    `0-2s: accroche directe sur ${idea.hook}, cadrage serré`,
    "2-6s: démonstration de l'astuce en 2-3 étapes visuelles claires",
    "6-8s: résultat + punchline, logo Nuklear en overlay léger",
  ];
  let genPrompt = `Format: vidéo courte verticale 9:16, 8s max, style ${idea.tone}.\nConcept: ${concept}.\nAccroche: ${idea.hook}\nDécoupage:\n${beats.map(b => "- " + b).join("\n")}\nContraintes: texte ajouté en post-prod (police Inter) ; logo Nuklear en incrustation légère dernière seconde ; rythme dynamique.`;
  try {
    const refined = await ollamaComplete.call(this, OLLAMA_MODEL,
      `Tu es directeur créatif vidéo short-form pour Nuklear. Réécris UN prompt de génération vidéo précis à partir du concept/découpage fournis, style ${idea.tone}, français parfait. Réponds uniquement par le prompt.`,
      `Concept: ${concept}\nAccroche: ${idea.hook}\nDécoupage:\n${beats.map(b => "- " + b).join("\n")}`, false);
    if (refined && refined.trim()) genPrompt = refined.trim();
  } catch (e) { /* on garde le prompt template */ }
  result.text = `🎬 *Prompt vidéo virale* (concept: ${concept})\n\nAccroche: ${idea.hook}\n\nDécoupage:\n${beats.map(b => "  " + b).join("\n")}\n\n*Prompt de génération:*\n${genPrompt}`;
}

else if (command === "gen_recrutement") {
  // Commande UTILITAIRE : champs saisis PRÉCISÉMENT par l'équipe, AUCUNE invention par le LLM (email/
  // contrat/lieu doivent être exacts). Rendu DIRECT (pas de propose-puis-"ok", contrairement à
  // gen_image) : il n'y a pas d'"idée" à valider, juste des champs à mettre en forme.
  const parts = freeText.split("|").map(s => s.trim()).filter(Boolean);
  const poste = parts[0];
  if (!poste) {
    result.text = "Format attendu : *gen recrutement: <poste> | <contrat> | <lieu> | <email>*\nEx: gen recrutement: Développeur Full Stack Senior | CDI | Antananarivo | recrutement@nuklear.io";
  } else {
    const fields = {
      poste,
      contrat: parts[1] || "CDI",
      lieu: parts[2] || "Antananarivo",
      email: parts[3] || "recrutement@nuklear.io",
    };
    const bgId = await resolveBrandBackground.call(this);
    const r = await tryTiers.call(this, buildRecruitmentTiers(fields, bgId));
    if (!r.tier) {
      result.text = `⚠️ Le montage du visuel recrutement a échoué. Réessaie dans un instant.\n\n_(diag: ${r.errors[r.errors.length - 1] || "inconnu"})_`;
    } else {
      result.image_url = r.tier.url;
      result.text = `✅ *Offre d'emploi prête à publier !*\n\n📌 ${fields.poste}\n📍 ${fields.contrat}, ${fields.lieu}\n✉️ ${fields.email}`;
    }
  }
}

else if (command === "gen_image" || command === "refresh" || command === "refine" ||
         command === "gen_collection" || command === "gen_avant_apres" || command === "gen_annonce") {
  // "refine" AJUSTE l'idée déjà proposée (previousIdea transmis) ; "refresh" en propose une
  // TOTALEMENT NOUVELLE (previousIdea = null) -- ne pas confondre les deux, comme côté Python
  // (orchestrator.py::_handle_refresh vs _handle_refine, testé explicitement).
  const previousIdea = (command === "refine") ? state.current_idea : null;
  const freeTextCommands = ["refine", "gen_image", "gen_collection", "gen_avant_apres", "gen_annonce"];
  const hint = freeTextCommands.includes(command) ? freeText : null;
  const forcedCategoryMap = { gen_collection: "collection", gen_avant_apres: "avant_apres", gen_annonce: "annonce" };
  const forcedCategory = forcedCategoryMap[command] || null;
  const idea = await synthesizeIdea.call(this, platform, hint, previousIdea, forcedCategory);
  // Filet de sécurité : force la catégorie même si le LLM ne l'a pas suivie à la lettre (fiabilité
  // garantie, indépendante de la détection automatique -- voir Extract & Route).
  if (forcedCategory) idea.category = forcedCategory;
  staticData.sessions[sender] = { stage: "idea_proposed", platform, current_idea: idea, refine_notes: state.refine_notes || [] };
  const prefix = command === "refresh" ? "🔄 Nouvelle proposition:\n\n" : (command === "refine" ? "✏️ Idée adaptée:\n\n" : "");
  result.text = prefix + formatIdea(idea, platform);
}

else if (command === "validate") {
  const idea = state.current_idea;
  if (!idea) {
    // Garde-fou défensif : état incohérent (ne devrait pas arriver, Extract & Route l'exige) --
    // on ne crashe jamais l'exécution (ce qui laisserait WhatsApp sans réponse).
    staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [] };
    result.text = "Rien à valider. Lance d'abord *gen image insta*.";
    return [{ json: result }];
  }
  let chosen = null, lastError = "", uploadDiag = "";

  // Badge de catégorie (haut-droite) : 1er mot du ton, en capitales, ≤14 car., sans emoji -- cosmétique.
  const badge = String(idea.tone || "").split(/[\s,;/]+/)[0].toUpperCase().replace(/[^A-Z0-9ÉÈÀ]/g, "").slice(0, 14);
  const presetConfigured = CLOUDINARY_UPLOAD_PRESET && CLOUDINARY_UPLOAD_PRESET.indexOf("REPLACE_WITH") === -1;
  const pexelsConfigured = PEXELS_KEY && PEXELS_KEY.indexOf("REPLACE_WITH") === -1;
  const illoUrl = buildIllustrationPrompt(idea); // illustration de marque Pollinations (déterministe)
  let illoWarm = false;
  // FOND DÉGRADÉ de marque : résolu UNE fois (upload initial puis cache) ; null = canevas noir uni.
  const bgId = await resolveBrandBackground.call(this);

  // ÉTAPE 0 -- GABARIT VIERGE fourni par l'utilisateur (fidélité charte maximale), si configuré.
  { const r = await tryTiers.call(this, buildTemplateTiers(idea.hook)); chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1]; }

  // ÉTAPE 0.5 -- ANNONCE (format PAYSAGE, texte structuré) : purement textuel, comme le gabarit
  // ci-dessus -- pas de Pexels, pas d'IA, rendu 100% fiable. Fond dédié (pool paysage, distinct du
  // pool portrait) résolu séparément puisque les deux formats ne partagent pas les mêmes assets.
  if (!chosen && idea.category === "annonce") {
    const bgIdLandscape = await resolveLandscapeBackground.call(this);
    const r = await tryTiers.call(this, buildAnnonceTiers(idea, bgIdLandscape));
    chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1];
  }

  // ÉTAPE 1 -- PHOTO(S) RÉELLE(S) de banque (Pexels, ZÉRO IA -> aucun faux texte possible) qui
  // ILLUSTRE(NT) l'idée. Nécessite une clé Pexels + un upload preset. Deux chemins selon la catégorie
  // auto-détectée : "avant_apres" cherche/uploade DEUX photos distinctes (split-screen) ; toute autre
  // catégorie (astuce, collection en repli) utilise une seule photo (mise en page 3 bandes). Repli
  // propre sur le poster de marque si indisponible dans tous les cas.
  if (!chosen && pexelsConfigured && presetConfigured && idea.category === "avant_apres") {
    // Recherche/upload SÉQUENTIELS (simple et fiable -- pas de concurrence à vérifier sans accès à
    // l'environnement Cloudinary réel).
    try {
      const beforeSubject = idea.visual_subject_before || `before state, problem: ${idea.visual_subject || idea.hook}`;
      const afterSubject = idea.visual_subject_after || `after state, success: ${idea.visual_subject || idea.hook}`;
      const beforeUrl = await pexelsSearchPhoto.call(this, beforeSubject);
      const afterUrl = beforeUrl ? await pexelsSearchPhoto.call(this, afterSubject) : null;
      if (beforeUrl && afterUrl) {
        const beforePid = await cloudinaryUploadFromUrl.call(this, beforeUrl);
        const afterPid = beforePid ? await cloudinaryUploadFromUrl.call(this, afterUrl) : null;
        if (beforePid && afterPid) {
          uploadDiag = "avant/après ok";
          const r = await tryTiers.call(this, buildBeforeAfterTiers(beforePid, afterPid, idea, bgId));
          chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1];
        } else uploadDiag = "upload avant/après incomplet";
      } else uploadDiag = "photo(s) avant/après introuvable(s)";
    } catch (e) { uploadDiag = extractHttpError(e); }
  }

  if (!chosen && pexelsConfigured && presetConfigured && idea.category === "collection") {
    // COLLECTION : plusieurs photos distinctes (jusqu'à 4), recherchées/uploadées séquentiellement.
    // deriveCollectionSubjects() garantit toujours 4 sujets cohérents, même si le LLM a classé l'idée
    // en "collection" sans remplir visual_subjects -- avant ce garde-fou, ce cas retombait
    // SILENCIEUSEMENT sur le template "astuce" à une seule photo (voir commentaire de la fonction).
    // En dessous de 2 photos réellement obtenues (échec Pexels/Cloudinary), on abandonne la grille et
    // on retombe sur le chemin "photo unique" ci-après (mieux vaut UNE photo nette qu'une grille vide).
    try {
      const subjects = deriveCollectionSubjects(idea);
      const pids = [];
      for (const subj of subjects) {
        const url = await pexelsSearchPhoto.call(this, subj);
        if (url) { const pid = await cloudinaryUploadFromUrl.call(this, url); if (pid) pids.push(pid); }
      }
      if (pids.length >= 2) {
        uploadDiag = `collection ok (${pids.length}/${subjects.length})`;
        const r = await tryTiers.call(this, buildCollectionTiers(pids, idea, bgId));
        chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1];
      } else uploadDiag = `collection insuffisante (${pids.length} photo(s))`;
    } catch (e) { uploadDiag = extractHttpError(e); }
  }

  if (!chosen && pexelsConfigured && presetConfigured) {
    try {
      const photoUrl = await pexelsSearchPhoto.call(this, idea.visual_subject || idea.hook);
      if (photoUrl) {
        const photoPid = await cloudinaryUploadFromUrl.call(this, photoUrl);
        if (photoPid) { uploadDiag = "photo ok"; const r = await tryTiers.call(this, buildPhotoEditorialTiers(photoPid, idea, bgId)); chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1]; }
        else uploadDiag = "upload photo sans public_id";
      } else uploadDiag = "aucune photo Pexels trouvée";
    } catch (e) { uploadDiag = extractHttpError(e); }
  }

  // ÉTAPE 2 -- POSTER DE MARQUE DÉTERMINISTE (repli fiable). Canevas sombre + logo (haut-gauche) +
  // kicker orange + H1 blanc + slogan bas-centre, uniquement à partir d'ASSETS STOCKÉS. Aucune IA,
  // aucun texte parasite possible, aucune dépendance fragile (ni "Fetched URL" ni upload). Rendu
  // IDENTIQUE et prêt à publier À CHAQUE FOIS -> zéro génération gaspillée en résultats inpubliables.
  if (!chosen) { const r = await tryTiers.call(this, buildBrandCanvasTiers(idea.hook, badge, idea.kicker, bgId)); chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1]; }

  // ÉTAPE 3 -- ILLUSTRATION IA (OPTIONNELLE, désactivée par défaut : ENABLE_AI_ILLUSTRATION=false).
  // Le tier-gratuit Pollinations incruste de FAUX textes/objets dans l'image -> rendus catastrophiques.
  // À n'activer qu'avec une source d'image FIABLE (idéalement des photos de marque stockées).
  if (!chosen && ENABLE_AI_ILLUSTRATION && presetConfigured) {
    try {
      await this.helpers.httpRequest({ method: "GET", url: illoUrl, timeout: 75000, json: false });
      illoWarm = true;
      const publicId = await cloudinaryUploadFromUrl.call(this, illoUrl);
      if (publicId) { uploadDiag = "ok"; const r = await tryTiers.call(this, buildIllustrationCompositeTiers(publicId, idea)); chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1]; }
      else uploadDiag = "réponse upload sans public_id";
    } catch (e) { uploadDiag = extractHttpError(e); }
  } else if (!ENABLE_AI_ILLUSTRATION) {
    uploadDiag = "illustration IA désactivée -> poster de marque déterministe";
  }

  // ÉTAPE 4 -- ultimes filets (FETCH puis image brute), UNIQUEMENT si l'IA a été activée et préchauffée.
  if (!chosen && illoWarm) {
    { const r = await tryTiers.call(this, buildFetchTiers(illoUrl, idea.hook)); chosen = r.tier; if (r.errors.length) lastError = r.errors[r.errors.length - 1]; }
    if (!chosen) chosen = { label: "image brute", url: illoUrl, raw: true };
  }

  if (!chosen) {
    staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [] };
    result.text = `⚠️ Le générateur d'image (Pollinations) n'a pas répondu à temps. Réessaie dans un instant.\n\n_(diag: ${lastError})_`;
    return [{ json: result }];
  }

  staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [] };
  result.image_url = chosen.url;
  const diagTail = uploadDiag ? `upload=${uploadDiag} ; ${lastError}` : lastError;
  // LÉGENDE PRÊTE À PUBLIER envoyée AVEC l'image : caption on-brand + hashtags populaires, pour que
  // l'équipe n'ait qu'à copier-coller lors de la publication (demande utilisateur).
  const caption = String(idea.caption || idea.hook || "");
  const tags = (idea.hashtags && idea.hashtags.length) ? idea.hashtags.join(" ") : "";
  const post = `${caption}${tags ? "\n\n" + tags : ""}`;
  // Rendu "complet" = illustration composée (tous crans), gabarit auto, ou gabarit fourni + texte.
  // Reconnaît TOUS les labels de rendu "complet" (chaque builder a ses propres libellés) -- avant ce
  // correctif, les nouveaux templates (collection/avant-après/annonce) n'étaient reconnus par AUCUN
  // de ces mots-clés et s'affichaient donc TOUJOURS comme "montage partiel", même en cas de succès.
  const isFull = ["illustration", "gabarit auto", "photo", "+ texte", "collection", "avant-après", "annonce"].some(s => chosen.label && chosen.label.indexOf(s) !== -1);
  if (chosen.raw) {
    result.text = `✅ *Visuel prêt* (montage simplifié) :\n\n${post}\n\n_(diag: ${diagTail || "montage désactivé"})_`;
  } else if (!isFull) {
    result.text = `✅ *Visuel prêt* (montage partiel : ${chosen.label}) :\n\n${post}`;
  } else {
    result.text = `✅ *Prêt à publier !*\n\n${post}`;
  }
}

return [{ json: result }];
